#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

# All customization is below the template's STAGES marker.
set +x
umask 077
[[ -t 0 ]] || { printf 'Run this wizard in your own interactive terminal.\n' >&2; exit 1; }
SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
PROJECT_DIR=$(cd -- "$SCRIPT_DIR/.." && pwd)
cd -- "$PROJECT_DIR"
ENV_FILE="$PROJECT_DIR/.env.local"
TOKEN_PAGE="https://console.mapbox.com/account/access-tokens/"
TOKEN_KIND="dedicated"

# Only dotenv's simple outer quotes are accepted; env files are never executed.
unquote_token() {
  local value="$1"
  case "$value" in
    \"*\") value=${value#\"}; value=${value%\"} ;;
    \'*\') value=${value#\'}; value=${value%\'} ;;
  esac
  printf '%s' "$value"
}

valid_public_token() {
  [[ "$1" =~ ^pk\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$ ]]
}

check_env_target() {
  [[ ! -L "$ENV_FILE" ]] || { warn '.env.local is a symlink; use a regular file.'; return 1; }
  [[ ! -e "$ENV_FILE" || -f "$ENV_FILE" ]] || { warn '.env.local must be a regular file.'; return 1; }
  git check-ignore -q --no-index -- .env.local || { warn '.env.local must be gitignored before saving.'; return 1; }
  if git ls-files --error-unmatch -- .env.local >/dev/null 2>&1; then
    warn '.env.local is tracked by Git. Resolve that before saving credentials.'
    return 1
  fi
}

capture_public_token() {
  local candidate
  while :; do
    ask_secret NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN 'Paste only your public pk. token (input hidden):'
    candidate=$(unquote_token "$NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN")
    if valid_public_token "$candidate"; then
      NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN="$candidate"
      return 0
    fi
    warn 'Expected pk.<payload>.<signature>, with no spaces or KEY= prefix.'
    say 'Secret sk. tokens and temporary tk. tokens are not accepted here.'
    confirm 'Try again?' || return 1
  done
}

banner 'RescueSync - local Mapbox token setup'

stage 'Review the local-only setup'
say '1. Confirm the procedure and check the ignored local env destination.'
say '2. Open Mapbox and create or select a public browser token.'
say '3. Capture NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN into .env.local.'
say '4. Review local restart and future hosting instructions.'
note 'Only one public browser token is captured; no secret Mapbox key or account password is saved.'
note 'Existing database/auth settings are preserved. No cloud writes or deployment commands run.'
confirm 'Continue with these four stages and allow the local token setting to be saved?' || exit 0
command -v git >/dev/null 2>&1 || { warn 'Git is required for the env-file safety check.'; exit 1; }
[[ -f package.json && -f vercel.json ]] || { warn 'Expected this script inside RescueSync/scripts.'; exit 1; }
check_env_target || exit 1

stage 'Create or select a public Mapbox token'
open_url "$TOKEN_PAGE"
step 'Sign in to your existing Mapbox account, or complete sign-up in the browser.'
step 'Open Access tokens. Prefer a separate token named RescueSync local.'
note 'Required public scopes: styles:read and fonts:read. No secret scopes are needed.'
note 'Trial accounts may offer only a default public token; adding a payment method is your decision.'
if confirm 'Can your account create a dedicated public token?'; then
  step 'Click Create a token, name it RescueSync local, and select styles:read and fonts:read.'
  step 'Leave secret scopes off. Add http://localhost:3000 as an allowed URL.'
  note 'If you use another local port, explicitly allow that exact localhost URL too.'
  note 'Wildcards and IP addresses are unsupported; use localhost instead of 127.0.0.1.'
  step 'Click Create token and complete any password confirmation in Mapbox itself.'
  step 'Copy the resulting token beginning with pk.'
else
  TOKEN_KIND="default"
  step 'Copy the Default public token beginning with pk. from the console.'
  note 'Default tokens cannot have URL restrictions. This fallback is for local development.'
  note 'Before hosting, use a dedicated restricted token if your account allows it.'
fi
pause 'With the token copied, press Enter to paste it in the next stage.'

stage 'Save the public token locally'
open_url "$TOKEN_PAGE"
say 'Paste the token below. Nothing you paste is printed or sent to a validation service.'
note 'Enter keeps an existing saved value. Pasting a new value replaces only this setting.'
capture_public_token || exit 1
check_env_target || exit 1
if [[ -f "$ENV_FILE" ]]; then chmod 600 "$ENV_FILE"; fi
write_env NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN "$NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN"
chmod 600 "$ENV_FILE"
unset NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN
say 'Saved the public token with owner-only file permissions.'
note 'This checks token shape only; account validity, scopes, and URL restrictions still need a map test.'
pause 'Press Enter to review what happens next.'

stage 'Review local use and future hosting'
say 'Restart the local Next.js process after an environment change: bun run dev'
say 'The map feature is still awaiting implementation approval; saving a token does not enable it.'
say 'A future browser map test must confirm the style, fonts, and tiles load from localhost.'
if [[ "$TOKEN_KIND" = default ]]; then
  note 'This run used the local default-token path; URL restrictions were not configured by the wizard.'
fi
say 'For future Vercel hosting, create a separate public token allowing https://rescuesync.vercel.app.'
note 'Allow exact additional preview/custom origins when needed; do not allow all of vercel.app.'
say 'Later, add NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN in the intended Vercel environment and rebuild.'
note 'No Vercel values, GitHub secrets, account billing, or deployments were changed by this script.'
pause 'Press Enter for the setup summary.'
finish
